32	/**
33	 * This filter captures the request that was sent out via WebClient so that the execution response can
34	 * accurately represent the actual request used
35	 */
36	@Getter
37	public class RequestCaptureFilter implements ExchangeFilterFunction {
38	
39	    private ClientRequest request;
40	    private final ObjectMapper objectMapper;
41	    private final BodyReceiver bodyReceiver = new BodyReceiver();
42	
43	    public RequestCaptureFilter(ObjectMapper objectMapper) {
44	        this.objectMapper = objectMapper;
45	    }
46	
47	    @Override
48	    @NonNull public Mono<ClientResponse> filter(@NonNull ClientRequest request, ExchangeFunction next) {
49	        this.request = request;
50	        return next.exchange(request);
51	    }
52	
53	    public ActionExecutionRequest populateRequestFields(
54	            ActionExecutionRequest existing, boolean isBodySentWithApiRequest) {
55	        final ActionExecutionRequest actionExecutionRequest = new ActionExecutionRequest();
56	
57	        if (request == null) {
58	            // The `request` can be null, if there's another filter function before `this.filter`,
59	            // which returns a `Mono.error` instead of the request object.
60	            return actionExecutionRequest;
61	        }
62	
63	        actionExecutionRequest.setUrl(request.url().toString());
64	        actionExecutionRequest.setHttpMethod(request.method());
65	        MultiValueMap<String, String> headers =
66	                CollectionUtils.toMultiValueMap(new LinkedCaseInsensitiveMap<>(8, Locale.ENGLISH));
67	        AtomicBoolean isMultipart = new AtomicBoolean(false);
68	        request.headers().forEach((header, value) -> {
69	            if (HttpHeaders.AUTHORIZATION.equalsIgnoreCase(header) || "api_key".equalsIgnoreCase(header)) {
70	                headers.add(header, "****");
71	            } else {
72	                headers.addAll(header, value);
73	            }
74	            if (HttpHeaders.CONTENT_TYPE.equalsIgnoreCase(header)
75	                    && MULTIPART_FORM_DATA_VALUE.equalsIgnoreCase(value.get(0))) {
76	                isMultipart.set(true);
77	            }
78	        });
79	        actionExecutionRequest.setHeaders(objectMapper.valueToTree(headers));
80	
81	        actionExecutionRequest.setRequestParams(existing.getRequestParams());
82	        actionExecutionRequest.setExecutionParameters(existing.getExecutionParameters());
83	        actionExecutionRequest.setProperties(existing.getProperties());
84	
85	        // Apart from multipart, refer to the request that was actually sent
86	        if (!isMultipart.get()) {
87	            if (isBodySentWithApiRequest) {
88	                actionExecutionRequest.setBody(bodyReceiver.receiveValue(this.request.body()));
89	            }
90	        } else {
91	            actionExecutionRequest.setBody(existing.getBody());
92	        }
93	
94	        return actionExecutionRequest;
95	    }
96	
97	    public static ActionExecutionRequest populateRequestFields(
98	            ActionConfiguration actionConfiguration,
99	            URI uri,
100	            List<Map.Entry<String, String>> insertedParams,
101	            ObjectMapper objectMapper) {
102	
103	        ActionExecutionRequest actionExecutionRequest = new ActionExecutionRequest();
104	
105	        if (!insertedParams.isEmpty()) {
106	            final Map<String, Object> requestData = new HashMap<>();
107	            requestData.put("smart-substitution-parameters", insertedParams);
108	            actionExecutionRequest.setProperties(requestData);
109	        }
110	
111	        AtomicReference<String> reqContentType = new AtomicReference<>();
112	
113	        if (actionConfiguration.getHeaders() != null) {
114	            MultiValueMap<String, String> reqMultiMap =
115	                    CollectionUtils.toMultiValueMap(new LinkedCaseInsensitiveMap<>(8, Locale.ENGLISH));
116	
117	            actionConfiguration.getHeaders().forEach(header -> {
118	                if (HttpHeaders.CONTENT_TYPE.equalsIgnoreCase(header.getKey())) {
119	                    reqContentType.set((String) header.getValue());
120	                }
121	                reqMultiMap.put(header.getKey(), Arrays.asList((String) header.getValue()));
122	            });
123	            actionExecutionRequest.setHeaders(objectMapper.valueToTree(reqMultiMap));
124	        }
125	
126	        // If the body is set, then use that field as the request body by default
127	        if (actionConfiguration.getBody() != null) {
128	            actionExecutionRequest.setBody(actionConfiguration.getBody());
129	        }
130	
131	        if (MediaType.APPLICATION_FORM_URLENCODED_VALUE.equals(reqContentType.get())) {
132	            final List<Property> bodyFormData = actionConfiguration.getBodyFormData();
133	            Map<String, Object> bodyDataMap = new HashMap<>();
134	            bodyFormData
135	                    // Disregard keys that are null
136	                    .stream()
137	                    .filter(property -> property.getKey() != null)
138	                    .forEach(property -> bodyDataMap.put(property.getKey(), property.getValue()));
139	            actionExecutionRequest.setBody(bodyDataMap);
140	        } else if (MediaType.MULTIPART_FORM_DATA_VALUE.equals(reqContentType.get())) {
141	            final List<Property> bodyFormData = actionConfiguration.getBodyFormData();
142	            Map<String, Object> bodyDataMap = new HashMap<>();
143	            bodyFormData
144	                    // Disregard keys that are null
145	                    .stream()
146	                    .filter(property -> property.getKey() != null)
147	                    .forEach(property -> {
148	                        if (FILE_TYPE.equalsIgnoreCase(property.getType())) {
149	                            bodyDataMap.put(property.getKey(), "<file>");
150	                        } else {
151	                            bodyDataMap.put(property.getKey(), property.getValue());
152	                        }
153	                    });
154	            actionExecutionRequest.setBody(bodyDataMap);
155	        }
156	
157	        if (actionConfiguration.getHttpMethod() != null) {
158	            actionExecutionRequest.setHttpMethod(actionConfiguration.getHttpMethod());
159	        }
160	
161	        if (uri != null) {
162	            actionExecutionRequest.setUrl(uri.toString());
163	        }
164	
165	        return actionExecutionRequest;
166	    }
167	}
