99	    public BodyInserter<?, ?> buildBodyInserter(Object body, String contentType, Boolean encodeParamsToggle) {
100	        if (body == null) {
101	            return BodyInserters.fromValue(new byte[0]);
102	        }
103	        switch (contentType) {
104	            case MediaType.APPLICATION_JSON_VALUE:
105	                final Object bodyObject = parseJsonBody(body);
106	                return BodyInserters.fromValue(bodyObject);
107	            case MediaType.APPLICATION_FORM_URLENCODED_VALUE:
108	                final String formData = parseFormData((List<Property>) body, encodeParamsToggle);
109	                if ("".equals(formData)) {
110	                    return BodyInserters.fromValue(new byte[0]);
111	                }
112	                return BodyInserters.fromValue(formData);
113	            case MediaType.MULTIPART_FORM_DATA_VALUE:
114	                return parseMultipartFileData((List<Property>) body);
115	            case MediaType.TEXT_PLAIN_VALUE:
116	                return BodyInserters.fromValue((String) body);
117	            case MediaType.APPLICATION_OCTET_STREAM_VALUE:
118	                return parseMultimediaData((String) body);
119	            default:
120	                return BodyInserters.fromValue(((String) body).getBytes(StandardCharsets.ISO_8859_1));
121	        }
122	    }
