124	    public Object parseJsonBody(Object body) {
125	        try {
126	            if (body instanceof String) {
127	                // Setting the requestBody to an empty byte array here
128	                // since the an empty string causes issues with a signed request.
129	                // If the content of the SignableRequest is null, the query string parameters
130	                // will be encoded and used as the contentSha256 segment of the canonical request string.
131	                // This causes a SignatureMatch Error for signed urls like those generated by AWS S3.
132	                // More detail here - https://github.com/aws/aws-sdk-java/issues/2205
133	                if ("" == body) {
134	                    return new byte[0];
135	                }
136	                Object objectFromJson = objectFromJson((String) body);
137	                if (objectFromJson != null) {
138	                    body = objectFromJson;
139	                }
140	            }
141	        } catch (JsonSyntaxException | ParseException e) {
142	            throw new AppsmithPluginException(
143	                    AppsmithPluginError.PLUGIN_JSON_PARSE_ERROR, body, "Malformed JSON: " + e.getMessage());
144	        }
145	        return body;
146	    }
