175	        // This decoding for base64 is required because of
176	        // issue https://github.com/appsmithorg/appsmith/issues/32378
177	        // According to this if we tried to upload any multimedia files (img, audio, video)
178	        // It was not getting decoded before uploading on required URL
179	        if (requestBodyObj.contains(BASE64_DELIMITER)) {
180	            List<String> bodyArrayList = Arrays.asList(requestBodyObj.split(BASE64_DELIMITER));
181	            requestBodyObj = bodyArrayList.get(bodyArrayList.size() - 1);
182	
183	            // Using mimeDecoder here, since base64 conversion by file picker widget follows mime standard
184	            byte[] payload = Base64.getMimeDecoder().decode(bodyArrayList.get(bodyArrayList.size() - 1));
185	            return BodyInserters.fromValue(payload);
186	        }
187	
188	        return BodyInserters.fromValue(requestBodyObj);
189	    }
